from lib import *
S = SS('n21')
steps = [
    step("Gin 的 Context 实现了 context.Context,但默认什么都不转发:hasRequestContext 要求 engine.ContextWithFallback 为真且 Request.Context() 非 nil,否则 Deadline 返回 ok=false、Done 返回 nil、Err 返回 nil。Value 的顺序:先看是不是 ContextRequestKey / ContextKey,再看字符串键能不能在 c.Keys 里找到,最后才(在 fallback 打开时)去 Request.Context().Value(key) 找。", t=tl(S(1)), mark=lidx(S(1), 'hasFallback := c.engine != nil && c.engine.ContextWithFallback', 'if !c.hasRequestContext() {'), done=lidx(S(1), 'return c.Request.Context().Done()', 'if key == ContextRequestKey', 'if keyAsString, ok := key.(string); ok'), kv=KV([['默认', 'Done()==nil,Err()==nil,没有 Deadline'], ['Value', 'Keys → (fallback)Request.Context()'], ['开关', 'engine.ContextWithFallback']], ['默认'])),
    step("中间件给请求加了 100 ms 超时和一个 trace 值。ContextWithFallback=false:c.Done()==nil、c.Err()=nil、没有 Deadline;c.Value(\"user\") 能取到(来自 Keys),c.Value(ctxKey(\"trace\")) 是 nil(没有转发),而 c.Request.Context().Value 能取到 T-1;把 c 传给 work 函数时它没有被取消,自己跑满 400 ms;work(c.Request.Context()) 100 ms 就超时。ContextWithFallback=true:c.Done() 非 nil、有 Deadline、能取到 T-1;work(c) 在 102 ms 被取消。", t=tl(S(2)), mark=lidx(S(2), 'c.Done()==nil:true', 'ctxKey("trace"))=<nil>', '没有被取消,自己跑完'), done=lidx(S(2), 'c.Done()==nil:false', 'work(c):context deadline exceeded 取消(102 ms)'), b=bars([['false:work(c)', 400, '400 ms,没被取消'], ['false:work(c.Request.Context())', 101, '101 ms'], ['true:work(c)', 102, '102 ms']], 400, mark=[0], done=[1, 2]), kv=KV([['false', 'c 当 context 用是个“永不取消”的 context'], ['true', 'Done / Err / Deadline / Value 转发给 Request.Context()'], ['绕开', '直接用 c.Request.Context()']], ['false'])),
    step("用 c 作父 context 派生子 context(context.WithTimeout(c, 1500ms)),客户端在 200 ms 时断开连接:ContextWithFallback=false 时子 context 一直等到自己的 1500 ms 超时才结束(context deadline exceeded,1502 ms 后);true 时 202 ms 后就以 context canceled 结束。", t=tl(S(3)), mark=lidx(S(3), 'ContextWithFallback=false'), done=lidx(S(3), 'ContextWithFallback=true'), b=bars([['false:子 context 结束', 1502, '1502 ms(自己超时)'], ['true:子 context 结束', 202, '202 ms(随断开取消)']], 1502, mark=[0], done=[1]), kv=KV([['false', '客户端断开传不下去,白白等满超时'], ['true', '断开 → 取消 → 子 context 立刻结束']], ['false'])),
]
A = mkartn('n21', 21, 'Gin,Context,ContextWithFallback,context.Context,超时取消,Go,真实验证,动画演示',
    '在 Gin v1.12.0 里实测 ContextWithFallback:默认关闭时把 *gin.Context 当 context.Context 传下去永远不会被取消(Done 为 nil),也读不到 Request.Context() 里的值;打开后 Done / Err / Deadline / Value 都转发给 Request.Context();以 c 为父的子 context 在客户端断开时 202 ms 结束,关闭时要等满 1502 ms 的自身超时。',
    '很多人把 c 直接传给数据库或下游客户端当 context 用,以为请求取消时它们会跟着取消。默认并不会。这篇验证 ContextWithFallback 关闭和打开时 Done、Err、Deadline、Value 的行为,以及它对客户端断开时子 context 的影响。',
    [('400 ms', '默认配置下 work(c) 没有被请求超时取消,自己跑满的时间'), ('1502 ms vs 202 ms', '客户端 200 ms 断开后,以 c 为父的子 context 结束的时间(关闭 / 打开 fallback)'), ('T-1', '只有打开 fallback 后 c.Value 才能读到 Request.Context 里的 trace 值')],
    [('默认什么都不转发', '<p>*gin.Context 实现了 <code>context.Context</code> 接口,所以能直接传给接受 context 的函数,但默认的 <code>Done()</code> 是 nil、<code>Err()</code> 是 nil、没有 deadline。也就是说,它对下游来说是一个永远不会取消的 context;<code>c.Value</code> 只能读到 <code>c.Keys</code> 里的值,读不到 <code>Request.Context()</code> 里的。</p>'),
     ('打开之后', '<p><code>engine.ContextWithFallback = true</code> 后,四个方法都转发给 <code>c.Request.Context()</code>:中间件加的超时会让 <code>work(c)</code> 在 100 ms 左右被取消,trace 值也能读到。不想打开这个开关时,每次传 <code>c.Request.Context()</code> 也能得到同样的效果,代价是每个调用点都得记得这样写。</p>'),
     ('子 context 与客户端断开', '<p>以 <code>c</code> 为父创建子 context,打开 fallback 时,客户端断开会通过 <code>Request.Context()</code> 的取消传下来(202 ms);关闭时子 context 对断开一无所知,只能等自己的超时(1502 ms)。如果 handler 里有耗时的下游调用,这就是“客户端早走了,服务端还在白干”的来源之一。</p>')],
    steps,
    [ENV_N_GIN + '。第二节用真实的 httptest.NewServer 与 http.Client;第三节用原始 TCP 连接发 GET 并在 200 ms 时关闭;每种情形各一次',
     '没有验证:fallback 打开时 Value 的查找开销;用 c 作 context 传给真实数据库驱动或 HTTP 客户端的行为(只用了自写的等待函数和 context.WithTimeout);ContextWithFallback 默认为 false 的历史原因(没有查证)'],
    'ContextWithFallback')
